/**
 * Language capability registry — the single source of truth for which
 * language can do what in KagazBol.
 *
 * Provider support below was checked against docs.sarvam.ai on 2026-10-22:
 *  - Document Digitization `job_parameters.language` list
 *  - Text LID (`POST /text-lid`) language list
 *  - Saaras STT `language_code` list
 *  - Bulbul v3 TTS `language_code` list
 * "explanation" means KagazBol's own prompts + UI strings exist for that language.
 * Explanations are generated by Sarvam chat models; that is "supported", not "benchmarked".
 *
 * Keep this file in sync with the provider docs when models change.
 */

export type CapabilityStatus = "supported" | "unsupported";

export interface LanguageCapabilities {
  code: string;
  name: string;
  nativeName: string;
  /** Script used for rendering hints. */
  script: "Latn" | "Deva" | "Beng" | "Gujr" | "Knda" | "Mlym" | "Orya" | "Guru" | "Taml" | "Telu";
  ocr: CapabilityStatus;
  detection: CapabilityStatus;
  stt: CapabilityStatus;
  tts: CapabilityStatus;
  /** KagazBol can explain documents and answer questions in this language. */
  explanation: CapabilityStatus;
  /** UI strings are translated. */
  ui: CapabilityStatus;
}

const S = "supported" as const;
const U = "unsupported" as const;

export const LANGUAGE_REGISTRY: readonly LanguageCapabilities[] = [
  { code: "en-IN", name: "English", nativeName: "English", script: "Latn", ocr: S, detection: S, stt: S, tts: S, explanation: S, ui: S },
  { code: "hi-IN", name: "Hindi", nativeName: "हिंदी", script: "Deva", ocr: S, detection: S, stt: S, tts: S, explanation: S, ui: S },
  { code: "mr-IN", name: "Marathi", nativeName: "मराठी", script: "Deva", ocr: S, detection: S, stt: S, tts: S, explanation: S, ui: S },
  // Readable and detectable by the provider, but KagazBol does not yet explain in these.
  { code: "bn-IN", name: "Bengali", nativeName: "বাংলা", script: "Beng", ocr: S, detection: S, stt: S, tts: S, explanation: U, ui: U },
  { code: "gu-IN", name: "Gujarati", nativeName: "ગુજરાતી", script: "Gujr", ocr: S, detection: S, stt: S, tts: S, explanation: U, ui: U },
  { code: "kn-IN", name: "Kannada", nativeName: "ಕನ್ನಡ", script: "Knda", ocr: S, detection: S, stt: S, tts: S, explanation: U, ui: U },
  { code: "ml-IN", name: "Malayalam", nativeName: "മലയാളം", script: "Mlym", ocr: S, detection: S, stt: S, tts: S, explanation: U, ui: U },
  { code: "od-IN", name: "Odia", nativeName: "ଓଡ଼ିଆ", script: "Orya", ocr: S, detection: S, stt: S, tts: S, explanation: U, ui: U },
  { code: "pa-IN", name: "Punjabi", nativeName: "ਪੰਜਾਬੀ", script: "Guru", ocr: S, detection: S, stt: S, tts: S, explanation: U, ui: U },
  { code: "ta-IN", name: "Tamil", nativeName: "தமிழ்", script: "Taml", ocr: S, detection: S, stt: S, tts: S, explanation: U, ui: U },
  { code: "te-IN", name: "Telugu", nativeName: "తెలుగు", script: "Telu", ocr: S, detection: S, stt: S, tts: S, explanation: U, ui: U },
];

/** Languages a user can choose for explanations, answers and the interface. */
export const APP_LANGUAGES = ["en-IN", "hi-IN", "mr-IN"] as const;
export type AppLanguage = (typeof APP_LANGUAGES)[number];
export const DEFAULT_LANGUAGE: AppLanguage = "en-IN";

export function isAppLanguage(value: unknown): value is AppLanguage {
  return typeof value === "string" && (APP_LANGUAGES as readonly string[]).includes(value);
}

/**
 * Normalises loose language identifiers ("hi", "HI-in", "hin", "marathi") to the
 * canonical BCP-47 code used everywhere in the app. Returns null when unknown.
 */
export function normalizeLanguageCode(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const v = value.trim().toLowerCase().replace("_", "-");
  if (!v) return null;
  const aliases: Record<string, string> = {
    en: "en-IN", eng: "en-IN", english: "en-IN",
    hi: "hi-IN", hin: "hi-IN", hindi: "hi-IN",
    mr: "mr-IN", mar: "mr-IN", marathi: "mr-IN",
    bn: "bn-IN", gu: "gu-IN", kn: "kn-IN", ml: "ml-IN", od: "od-IN", or: "od-IN",
    pa: "pa-IN", ta: "ta-IN", te: "te-IN",
  };
  if (aliases[v]) return aliases[v];
  const match = LANGUAGE_REGISTRY.find((l) => l.code.toLowerCase() === v);
  if (match) return match.code;
  // "hi-in" style with a non-IN region still maps to the Indian variant we support.
  const base = v.split("-")[0];
  return aliases[base] ?? null;
}

export function getLanguage(code: string): LanguageCapabilities | undefined {
  const norm = normalizeLanguageCode(code);
  return LANGUAGE_REGISTRY.find((l) => l.code === norm);
}

export function languageName(code: string, native = false): string {
  const l = getLanguage(code);
  if (!l) return code;
  return native ? l.nativeName : l.name;
}

export function hasCapability(code: string, cap: keyof Pick<LanguageCapabilities, "ocr" | "detection" | "stt" | "tts" | "explanation" | "ui">): boolean {
  return getLanguage(code)?.[cap] === "supported";
}

/**
 * Response-language policy (see docs/VOICE.md):
 * 1. An explicit choice for this request wins.
 * 2. Otherwise a confident detection of the user's spoken question, if we can answer in it.
 * 3. Otherwise the saved preference.
 * We never silently switch on an uncertain detection.
 */
export function resolveResponseLanguage(opts: {
  explicit?: string | null;
  detected?: string | null;
  detectedConfidence?: number | null;
  preferred: AppLanguage;
  confidenceThreshold?: number;
}): { language: AppLanguage; reason: "explicit" | "detected" | "preference"; needsConfirmation: boolean } {
  const threshold = opts.confidenceThreshold ?? 0.75;
  if (opts.explicit && isAppLanguage(opts.explicit)) {
    return { language: opts.explicit, reason: "explicit", needsConfirmation: false };
  }
  const detected = normalizeLanguageCode(opts.detected);
  if (detected && isAppLanguage(detected) && detected !== opts.preferred) {
    const conf = opts.detectedConfidence;
    if (conf != null && conf >= threshold) {
      return { language: detected, reason: "detected", needsConfirmation: false };
    }
    // Detected a different language but not confidently: keep preference, ask.
    return { language: opts.preferred, reason: "preference", needsConfirmation: true };
  }
  return { language: opts.preferred, reason: "preference", needsConfirmation: false };
}
